package fable.hideseek.imba.client;import fable.hideseek.imba.config.OverlayBarrierConfig;import fable.hideseek.imba.game.OverlayBarrierRuntime;import fable.hideseek.imba.net.OverlayBarrierNetworking;import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking;import java.util.ArrayList;public final class OverlayBarrierClientNetworking{private OverlayBarrierClientNetworking(){}public static void register(){ClientPlayNetworking.registerGlobalReceiver(OverlayBarrierNetworking.SYNC,(client,handler,buf,sender)->{int count=Math.max(0,Math.min(100000,buf.readVarInt()));var list=new ArrayList<OverlayBarrierConfig.Entry>();for(int i=0;i<count;i++)list.add(new OverlayBarrierConfig.Entry(buf.readString(128),buf.readInt(),buf.readInt(),buf.readInt()));client.execute(()->OverlayBarrierRuntime.replaceClient(list));});}}
